//! Request builders for the `codex app-server` wire protocol (#2754).
//!
//! Every payload RSI sends to the app-server is built here, so the conformance tests
//! (`wire_conformance_tests`) validate the same bytes the provider writes against the JSON schema
//! `codex app-server generate-json-schema --experimental` emits. The fixtures per validated CLI
//! version live in `fixtures/schema-<version>/` and are regenerated by
//! `scripts/refresh-codex-schema-fixtures.sh <version>`.
//!
//! # `experimentalApi`
//!
//! `initialize` declares `capabilities.experimentalApi = true` only because `thread/start`
//! `dynamicTools` is an experimental field: the stable schema (`generate-json-schema`) has no
//! `dynamicTools` property and the app-server answers a stable client that sends one with
//! `dynamicTools requires experimentalApi capability`. `InitializeCapabilities.experimentalApi`
//! ("Opt into receiving experimental API methods and fields") is the opt-in. If the dynamic tools
//! ever become stable, or are dropped, so can this flag; the conformance tests pin the
//! stable/experimental split in the fixtures so a drift is loud.

use crate::claude::LaunchConfig;
use serde_json::{Value, json};
use std::path::Path;

/// `InitializeParams`: `clientInfo{name,title,version}` is required; `capabilities.experimentalApi`
/// is required for `dynamicTools` (see the module docs).
pub(crate) fn initialize_params() -> Value {
    json!({
        "clientInfo": {
            "name": "rsi",
            "title": "rsi",
            "version": env!("CARGO_PKG_VERSION"),
        },
        "capabilities": {
            "experimentalApi": true,
        },
    })
}

/// The `initialized` client notification (`ClientNotification`). A JSON-RPC notification carries no
/// `id` and no `params`.
pub(crate) fn initialized_notification() -> Value {
    json!({
        "jsonrpc": "2.0",
        "method": "initialized",
    })
}

/// One `UserInput` text item. `turn/start` `input` is an array of these, never a bare string.
pub(super) fn user_input_text(text: &str) -> Value {
    json!({"type": "text", "text": text})
}

/// `DynamicToolSpec` (function variant): the schema key on the wire is `inputSchema`.
fn dynamic_tool_spec(spec: &crate::tool_registry::ToolSpec) -> Value {
    json!({
        "type": "function",
        "name": spec.name,
        "description": spec.description,
        "inputSchema": spec.parameters,
    })
}

/// `ThreadStartParams`. The app-server has no `input` on `thread/start`: the launch query is
/// delivered by the first `turn/start` ([`turn_start_params`]).
pub(super) fn build_thread_start_params(
    config: &LaunchConfig,
    working_dir: &Path,
    tool_specs: &[crate::tool_registry::ToolSpec],
) -> Value {
    let dynamic_tools: Vec<Value> = tool_specs.iter().map(dynamic_tool_spec).collect();

    let mut params = serde_json::Map::new();
    params.insert("cwd".to_string(), json!(working_dir.display().to_string()));
    params.insert("dynamicTools".to_string(), json!(dynamic_tools));
    if let Some(model) = &config.model {
        params.insert("model".to_string(), json!(model));
    }
    if let Some(system_prompt) = &config.system_prompt {
        params.insert("developerInstructions".to_string(), json!(system_prompt));
    }
    Value::Object(params)
}

/// `TurnStartParams`: `threadId` and `input` (`UserInput[]`) are required.
pub(super) fn turn_start_params(thread_id: &str, cwd: &str, input: &str) -> Value {
    json!({
        "threadId": thread_id,
        "input": [user_input_text(input)],
        "cwd": cwd,
    })
}

/// `ThreadResumeParams`: only `threadId` is required. RSI has no resume path yet; the builder is
/// pinned against the schema so one added later starts conformant.
#[cfg(test)]
pub(super) fn thread_resume_params(thread_id: &str, working_dir: &Path) -> Value {
    json!({
        "threadId": thread_id,
        "cwd": working_dir.display().to_string(),
    })
}
